#include <stdio.h>

/* teste do desafio fim-limpo — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   A captura do stdout acontece DENTRO do teste: freopen manda o stdout
   para o arquivo temporario, o teste chama a funcao do aluno e le de volta. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void tela(void);

SM_TEST(o_relatorio_termina_no_fim) {
    freopen("sm_saida.tmp", "w", stdout);
    tela();
    fflush(stdout);

    FILE *f = fopen("sm_saida.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a primeira linha", linha, "relatorio pronto\n",
              "o relatorio abre anunciando que esta pronto");
    fgets(linha, 80, f);
    checa_str("a segunda linha", linha, "nada deu errado\n",
              "a segunda frase vem depois da quebra de linha da primeira");
    fgets(linha, 80, f);
    checa_str("a terceira linha", linha, "fim: codigo 0\n",
              "a ultima frase anuncia o fim limpo do programa");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida acaba na terceira linha: nenhuma linha extra e aceita");
    fclose(f);
}

